# ── Read each investment summary in the SharePoint folder and pull out its figures ──
import json
import re

SP = "m365-sharepoint"
# File types the SharePoint connector can read as text.
READABLE = {"docx", "docm", "xlsx", "xlsm", "pptx", "pptm", "pdf", "doc", "xls", "ppt", "rtf", "odt", "ods", "odp",
            "txt", "csv", "tsv", "md", "htm", "html"}
MAX_FILES = 40
# Characters of each file sent to AI (the AI step's cap is 32,000 including the prompt).
MAX_TEXT = 24000
CLASSES = ["Australian equities", "International equities", "Property", "Fixed interest", "Cash", "Alternatives", "Other"]

PROMPT = (
    "This is one investment summary (a portfolio valuation, adviser review, platform report or broker statement). "
    "Pull out the figures it states, for the portfolio as a whole. Use only what the document says: put null when a "
    "figure isn't there, and don't estimate. Money is a plain number in dollars (no $ or commas; a loss or outflow is "
    "negative, fees are positive). Percentages are numbers like 2.36 for 2.36%. Dates are YYYY-MM-DD. "
    "net_contributions is money added minus money taken out (contributions, deposits, withdrawals, pension payments) "
    "for the period. allocation uses these asset classes only: " + ", ".join(CLASSES) + ". top_holdings is the five "
    "largest holdings by value. actions are follow-ups the document asks for (dates, decisions, rollovers, lodgements); "
    "notes are anything else a reviewer should know (big losses, missing data, an allocation off target)."
)
SHAPE = (
    '{"entity": str, "entity_type": "SMSF|Trust|Company|Individual|Partnership|Other", "provider": str|null, '
    '"as_at": "YYYY-MM-DD"|null, "period_start": "YYYY-MM-DD"|null, "opening_value": number|null, '
    '"closing_value": number|null, "net_contributions": number|null, "income": number|null, '
    '"franking_credits": number|null, "fees": number|null, "realised_gain": number|null, '
    '"unrealised_gain": number|null, "period_return_pct": number|null, '
    '"allocation": [{"asset_class": str, "value": number}], "top_holdings": [{"name": str, "code": str|null, "value": number}], '
    '"actions": [str], "notes": [str]}'
)


def _ext(name):
    m = re.search(r"\.([A-Za-z0-9]+)$", str(name or ""))
    return m.group(1).lower() if m else ""


def _err(exc):
    msg = str(exc)
    if msg.startswith("tool_error: "):
        msg = msg[len("tool_error: "):]
    if "no usable credential" in msg or "credential unavailable" in msg:
        return "the SharePoint connection needs connecting (Settings → Connections → m365-sharepoint)"
    return msg[:300]


def _num(v):
    if isinstance(v, bool) or v is None:
        return None
    if isinstance(v, (int, float)):
        return float(v)
    s = re.sub(r"[,$\s]", "", str(v))
    neg = s.startswith("(") and s.endswith(")")
    s = s.strip("()")
    try:
        n = float(s)
    except ValueError:
        return None
    return -n if neg else n


def _class(name):
    s = str(name or "").lower()
    if "international" in s or "global" in s or "overseas" in s:
        return "International equities"
    if "australian" in s or "domestic" in s or ("equit" in s or "share" in s):
        return "Australian equities"
    if "property" in s or "reit" in s or "real estate" in s:
        return "Property"
    if "fixed" in s or "bond" in s or "credit" in s or "income" in s:
        return "Fixed interest"
    if "cash" in s or "deposit" in s:
        return "Cash"
    if "alternative" in s or "private" in s or "hedge" in s or "infrastructure" in s or "commodit" in s:
        return "Alternatives"
    return "Other"


def _date(v):
    s = str(v or "")
    return s if re.match(r"^\d{4}-\d{2}-\d{2}$", s) else ""


def _clean(raw, f):
    d = raw if isinstance(raw, dict) else {}
    alloc = {}
    for a in d.get("allocation") or []:
        if isinstance(a, dict):
            v = _num(a.get("value"))
            if v is not None:
                c = _class(a.get("asset_class"))
                alloc[c] = round(alloc.get(c, 0.0) + v, 2)
    holdings = []
    for h in d.get("top_holdings") or []:
        if isinstance(h, dict) and _num(h.get("value")) is not None:
            holdings.append({"name": str(h.get("name") or "")[:80], "code": str(h.get("code") or "")[:12],
                             "value": _num(h.get("value"))})
    out = {
        "file": str(f.get("name") or ""),
        "url": str(f.get("webUrl") or ""),
        "entity": str(d.get("entity") or "").strip() or str(f.get("name") or ""),
        "entity_type": str(d.get("entity_type") or "Other"),
        "provider": str(d.get("provider") or ""),
        "as_at": _date(d.get("as_at")),
        "period_start": _date(d.get("period_start")),
        "allocation": alloc,
        "top_holdings": holdings[:5],
        "actions": [str(x)[:300] for x in (d.get("actions") or []) if str(x).strip()][:8],
        "notes": [str(x)[:300] for x in (d.get("notes") or []) if str(x).strip()][:8],
    }
    for k in ("opening_value", "closing_value", "net_contributions", "income", "franking_credits", "fees",
              "realised_gain", "unrealised_gain", "period_return_pct"):
        out[k] = _num(d.get(k))
    return out


link = str(params.get("folder_link") or "").strip()
portfolios = []
skipped = []
folder_name = ""
problem = ""

if not link:
    problem = "No folder link: paste the SharePoint folder's link (Share → Copy link) when you click Run now."
else:
    items = []
    cursor = None
    try:
        while True:
            args = {"cursor": cursor} if cursor else {"url": link, "page_size": 200}
            page = api.connectors.invoke(server=SP, tool="list_sharepoint_folder", args=args)
            if not isinstance(page, dict):
                raise ValueError("SharePoint sent back something unexpected")
            if not cursor:
                folder_name = str((page.get("folder") or {}).get("name") or "")
            items.extend(page.get("items") or [])
            cursor = page.get("nextCursor")
            if not cursor or len(items) >= 1000:
                break
    except Exception as exc:
        problem = "Couldn't open the folder: " + _err(exc)

    for f in sorted(items, key=lambda x: str(x.get("name") or "").lower()):
        name = str(f.get("name") or "")
        if f.get("isFolder"):
            skipped.append({"file": name, "reason": "subfolder (only files directly in the folder are read)"})
        elif _ext(name) not in READABLE:
            skipped.append({"file": name, "reason": "not a document type that can be read"})
        elif len(portfolios) >= MAX_FILES:
            skipped.append({"file": name, "reason": "over the " + str(MAX_FILES) + "-file limit for one run"})
        else:
            try:
                r = api.connectors.invoke(server=SP, tool="read_sharepoint_file",
                                          args={"drive_id": f.get("driveId"), "item_id": f.get("id"), "max_chars": MAX_TEXT})
            except Exception as exc:
                skipped.append({"file": name, "reason": _err(exc)})
                continue
            text = str((r or {}).get("text") or "") if isinstance(r, dict) else ""
            if not text.strip():
                note = str((r or {}).get("note") or "") if isinstance(r, dict) else ""
                skipped.append({"file": name, "reason": note or "no text found"})
                continue
            try:
                raw = api.ai.extract(prompt=PROMPT, input=text[:MAX_TEXT], schema_hint=SHAPE)
            except Exception as exc:
                skipped.append({"file": name, "reason": "AI couldn't read the figures (" + str(exc)[:200] + ")"})
                continue
            p = _clean(raw, f)
            if p["closing_value"] is None:
                skipped.append({"file": name, "reason": "no portfolio value found, so it doesn't look like an investment summary"})
                continue
            if isinstance(r, dict) and r.get("truncated"):
                p["notes"].append("Only the first " + str(MAX_TEXT) + " characters of this file were read.")
            portfolios.append(p)

    if not problem and not portfolios:
        problem = "No investment summaries found in " + (folder_name or "the folder") + "."

summary = (problem + " " if problem else "") + "Read " + str(len(portfolios)) + " investment summar" + \
    ("y" if len(portfolios) == 1 else "ies") + (", skipped " + str(len(skipped)) if skipped else "") + "."
